Who directed more movies, Akira Kurosawa.code:
import requests

def get_director_movie_count(director_name):
    url = f"https://api.themoviedb.org/3/search/person"
    params = {
        "api_key": "your_api_key",
        "query": director_name
    }
    response = requests.get(url, params=params)
    data = response.json()
    if data["results"]:
        director_id = data["results"][0]["id"]
        movie_count_url = f"https://api.themoviedb.org/3/person/{director_id}/movie_credits"
        movie_count_response = requests.get(movie_count_url, params={"api_key": "your_api_key"})
        movie_count_data = movie_count_response.json()
        return len(movie_count_data.get("crew", []))
    return 0

akira_movies = get_director_movie_count("Akira Kurosawa")
spielberg_movies = get_director_movie_count("Steven Spielberg")

if akira_movies > spielberg_movies:
    print("Akira Kurosawa directed more movies.")
elif spielberg_movies > akira_movies:
    print("Steven Spielberg directed more movies.")
else:
    print("Both directed the same number of movies.")

